"use strict";
function* execute(action,input,state){state=state||{};if(action==="metadata")action="detail";var result=yield* sourceExecute(action,input,state);result=result||{};if(result.error)throw new Error(result.error);if(result.drama)result.drama=normalizeDrama(result.drama);if(Array.isArray(result.items))result.items=result.items.map(function(row){if(row.drama){row.drama=normalizeDrama(row.drama);return row;}return row.sourceId?normalizeDrama(row):row;});result.state=state;return result;}
function normalizeDrama(row){return Object.assign({},row,{description:String(first(row,["description","desc","intro"])),episodes:Number(first(row,["episodes","totalEpisode","episodeCount"],0))||0,category:String(first(row,["category","categoryName"])),sourceId:String(row.sourceId||""),title:String(first(row,["title","name"],"未命名")),tags:array(row.tags).filter(function(value){return typeof value==="string";})});}
function query(params) { return Object.keys(params).sort().map(function(key){return encodeURIComponent(key)+"="+encodeURIComponent(String(params[key])).replace(/%20/g,"+");}).join("&"); }
function first(object,keys,fallback){for(var i=0;i<keys.length;i++){var value=object&&object[keys[i]];if(value!==undefined&&value!==null&&value!=="")return value;}return fallback===undefined?"":fallback;}
function array(value){return Array.isArray(value)?value:[];}
function url(value){var values=array(value&&value.url_list);for(var i=0;i<values.length;i++){if(/^https:\/\//.test(values[i]))return values[i];}return typeof value==="string"&&/^https:\/\//.test(value)?value:"";}
function* http(address,options){options=options||{};var response=yield {type:"http",url:address,method:options.method||"GET",headers:options.headers||{},body:options.body,credential:!!options.credential,sign:!!options.sign};if(!response||response.status!==200){var error=new Error("HTTP failed");error.sourceError="http";error.httpStatus=response&&response.status||0;throw error;}return response.text;}
function* json(address,options){var data=JSON.parse(yield* http(address,options));if(data.status_code&&data.status_code!==0)throw new Error("API status");return data;}
function empty(){return {items:[],hasMore:false};}
function assignment(body,pattern){var match=pattern.exec(body);if(!match)return null;var start=match.index+match[0].length;while(/\s/.test(body[start]||"")&&start<body.length)start++;var depth=0,quoted=false,escaped=false;for(var i=start;i<body.length;i++){var c=body[i];if(escaped){escaped=false;continue;}if(quoted&&c==='\\'){escaped=true;continue;}if(c==='"'){quoted=!quoted;continue;}if(quoted)continue;if(c==='{'||c==='[')depth++;else if(c==='}'||c===']'){if(--depth===0)return JSON.parse(body.slice(start,i+1));}}throw new Error("页面参数不完整");}
function nodes(body,selector){return Array.from(htmlSelect(body,selector));}
function nodeText(body,selector){var row=nodes(body,selector)[0];return row?String(row.text).replace(/\s+/g," ").trim():"";}
function attr(body,selector,key){var row=nodes(body,selector)[0];return row?row.attributes[key]||"":"";}
function single(drama,chapter){return {drama:drama,chapters:[chapter||{id:drama.sourceId,title:"播放",currentEpisode:1}]};}
function select(choices,height){choices=choices.filter(function(value){return value.url&&/^https:\/\//.test(value.url);}).sort(function(a,b){return b.height-a.height;});if(!choices.length)throw new Error("No playable media");var selected=height?choices.find(function(value){return value.height<=height;})||choices[choices.length-1]:choices[0];return {url:selected.url,quality:selected.height||0,qualities:choices.map(function(value){return value.height||0;}),headers:selected.headers||{},decryptionKey:selected.key||"",variants:[selected].concat(choices.filter(function(value){return value.url!==selected.url;})).slice(0,16).map(function(value){return {url:value.url,quality:value.height||0,headers:value.headers||{},decryptionKey:value.key||""};})};}

function hjData(value){return value.data!==undefined&&value.id===undefined&&value.items===undefined&&value.url===undefined?value.data:value;}
function* hjRequest(route,params,state){
 if(!state.token||Date.now()-Number(state.tokenAt||0)>3600000){var guest=yield* json("https://api.huangju.net/auth/guest",{method:"POST",headers:{"Content-Type":"application/json","Origin":"https://huangju.net","Referer":"https://huangju.net/"},body:JSON.stringify({deviceId:state.deviceId||(state.deviceId="xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx".replace(/[xy]/g,function(c){var n=Math.floor(Math.random()*16);return (c==='x'?n:(n&3)|8).toString(16);} )))});state.token=guest.token||(guest.data||{}).token;if(!state.token)throw new Error("剧果访客授权失败");state.tokenAt=Date.now();}
 var response=yield {type:"http",url:"https://api.huangju.net"+route+(params?"?"+query(params):""),method:"GET",headers:{Authorization:"Bearer "+state.token,"Origin":"https://huangju.net","Referer":"https://huangju.net/","Accept":"application/json","User-Agent":"Mozilla/5.0"}};
 if(response.status===401){state.token="";throw new Error("剧果访客授权过期，请重试");}if(response.status!==200)throw new Error("剧果请求失败");return {data:hjData(JSON.parse(response.text)),cookies:response.mediaCookies||[]};
}
function hjDrama(row,sourceId){var id=String(row.id||""),slug=String(row.slug||""),sid=sourceId||slug+"-"+id;if(!id||!row.title||!sid.endsWith("-"+id))throw new Error("剧果剧集信息无效");var names=array(row.categories).map(function(item){return typeof item==='string'?item:item.name;}).filter(Boolean);if(row.category)names.unshift(typeof row.category==='string'?row.category:row.category.name);return {id:"huangju:"+sid,source:"huangju",sourceId:sid,title:row.title,cover:url(row.coverUrl),description:row.description||"",episodes:Number(row.totalEpisodes)||0,category:names[0]||"短剧",tags:names,releaseStatus:row.status==="completed"?"finished":row.status||""};}
function* sourceExecute(action,input,state){
 if(action==="categories"){var value=(yield* hjRequest("/categories",null,state)).data;if(!Array.isArray(value)||value.length>300)throw new Error("剧果分类无效");return {items:[{id:"@new",name:"最新"}].concat(value.filter(function(row){return row.slug!=="hot";}).map(function(row){return {id:row.slug,name:row.name};}))};}
 if(action==="catalog"||action==="search"||action==="check"){var page=Number(input.page)||1,params={page:page};if(input.query)params.q=input.query;else if(input.category==="@new")params.sort="new";else if(input.category)params.category=input.category;else params.sort="hot";var value=(yield* hjRequest("/dramas",params,state)).data;if(!Array.isArray(value.items)||value.items.length>500||value.page&&Number(value.page)!==page)throw new Error("剧果目录页无效");var size=Number(value.pageSize)||20,pages=Math.ceil(Number(value.total)/size)||0;return {items:value.items.map(function(row){return hjDrama(row);}),page:page,totalPages:pages,hasMore:pages?page<pages:value.items.length>=size,count:value.items.length};}
 var drama=input.drama||{},sid=String(drama.sourceId||"");if(!sid||/[\/:?#%|\\]/.test(sid))throw new Error("剧果剧集标识无效");
 if(action==="detail"||action==="metadata"){var value=(yield* hjRequest("/dramas/"+encodeURIComponent(sid),null,state)).data;if(!Array.isArray(value.episodes)||value.episodes.length>10000)throw new Error("剧果分集目录无效");var seen={},chapters=value.episodes.filter(function(ep){return ep.playable!==false;}).map(function(ep,index){var id=String(ep.id||""),order=Number(ep.epNo)||index+1;if(!id||seen[id])throw new Error("剧果分集重复或无效");seen[id]=true;return {id:"huangju:"+sid+":"+id,episodeId:id,source:"huangju",title:"第 "+order+" 集",currentEpisode:order};}).sort(function(a,b){return a.currentEpisode-b.currentEpisode;});return {drama:hjDrama(value,sid),chapters:chapters};}
 if(action==="resolve"){var ep=input.chapter||{},id=String(ep.episodeId||String(ep.id||"").split(":").pop());if(!id||/[\/:?#%|\\]/.test(id))throw new Error("剧果分集标识无效");var value=yield* hjRequest("/play/"+encodeURIComponent(id),null,state);if(!url(value.data.url))throw new Error("剧果未返回播放地址");if(value.cookies.length!==3)throw new Error("剧果媒体凭据不完整");return {url:value.data.url,quality:0,qualities:[],headers:{Referer:"https://huangju.net/","User-Agent":"Mozilla/5.0"},mediaCookies:value.cookies,expiresAt:typeof value.data.expiresAt==="string"?Date.parse(value.data.expiresAt)||0:Number(value.data.expiresAt)||0};}
 throw new Error("剧果不支持此操作");
}
